/**
 * This phone's identity to the buddy relay: a random id, and the secret that proves it.
 *
 * Neither is derived from anything about the phone or the person — they are 128 and 256 random
 * bits, generated by the relay on first contact. The relay keeps the id and the SHA-256 of the
 * secret; nobody, us included, can work backwards from what it holds to a person.
 *
 * The secret lives in the **keychain (iOS) / keystore (Android)** rather than in MMKV, because it
 * is the one value on the phone that another party would find useful: with it you could read this
 * phone's buddy inbox and send flags as it. Everything else buddy mode stores — nicknames, icons,
 * today's marks — is worth nothing to anybody and lives in the ordinary store.
 *
 * ## Why it is not `expo-secure-store` any more
 *
 * It was, and only the app's JavaScript could read it. That stopped being enough the moment a seal
 * tap on a widget had to tell a buddy by itself (D180): that runs in a widget extension or a
 * broadcast receiver, with no React runtime anywhere, and a secret it cannot read is a notification
 * that waits until somebody opens the app. So it moved to `modules/buddy-nicknames` — the same
 * keychain and keystore, reached under an App Group access group / an Android Keystore key that
 * every process of this app can open.
 *
 * Phones that already have a secret keep it: the first read that finds the bridge empty looks in
 * `expo-secure-store` once, moves what it finds, and deletes the old copy. Nobody re-registers and
 * nobody loses a pair.
 *
 * Every call is wrapped: a keychain that will not open degrades to "buddy mode is not set up",
 * never to a crash on a screen somebody opened for something else.
 */

import {
  deleteBuddySecret,
  getBuddySecret,
  setBuddySecret,
} from '../../modules/buddy-nicknames';

/** The narrow slice of a keychain this module needs, so tests can supply their own. */
export interface SecureStorage {
  getItemAsync(key: string): Promise<string | null>;
  setItemAsync(key: string, value: string): Promise<void>;
  deleteItemAsync(key: string): Promise<void>;
}

export interface BuddyCredentials {
  deviceId: string;
  secret: string;
}

const KEY = 'buddyRelayCredentials';

/** An in-memory stand-in, used by tests and anywhere the keychain cannot be constructed. */
export function createMemorySecureStorage(seed?: Record<string, string>): SecureStorage {
  const map = new Map<string, string>(Object.entries(seed ?? {}));
  return {
    getItemAsync: async (key) => map.get(key) ?? null,
    setItemAsync: async (key, value) => void map.set(key, value),
    deleteItemAsync: async (key) => void map.delete(key),
  };
}

/**
 * The keychain the widget can read too — this app's own bridge module.
 *
 * It holds one secret, not a keyed map, so the key is ignored: there has only ever been one, and
 * giving native code a key space it does not need is a drawer for something else to end up in.
 */
export function createBridgeSecureStorage(): SecureStorage {
  return {
    getItemAsync: () => getBuddySecret(),
    setItemAsync: async (_key, value) => {
      const stored = await setBuddySecret(value);
      if (!stored) throw new Error('buddy secret not stored');
    },
    deleteItemAsync: () => deleteBuddySecret(),
  };
}

/**
 * The bridge, with one glance back at where the secret used to live.
 *
 * `expo-secure-store` is consulted **once per store**, and only when the bridge has nothing: a
 * phone that never had buddy mode pays one failed keychain read, and a phone that did moves its
 * secret across on the first sync after updating. A migration that cannot complete leaves the old
 * copy where it is and carries on with it — buddy mode then works exactly as it did before D180,
 * with the app doing all the telling.
 */
export function createMigratingSecureStorage(
  bridge: SecureStorage,
  legacy: SecureStorage
): SecureStorage {
  let lookedBack = false;

  return {
    async getItemAsync(key) {
      const current = await bridge.getItemAsync(key);
      if (typeof current === 'string' && current.length > 0) return current;
      if (lookedBack) return null;
      lookedBack = true;

      const inherited = await legacy.getItemAsync(key);
      if (typeof inherited !== 'string' || inherited.length === 0) return null;
      try {
        await bridge.setItemAsync(key, inherited);
        await legacy.deleteItemAsync(key);
      } catch {
        // Moved or not, the secret is valid and this phone is still itself to the relay.
      }
      return inherited;
    },

    async setItemAsync(key, value) {
      try {
        await bridge.setItemAsync(key, value);
      } catch (error) {
        // Somewhere safe beats somewhere shared: a bridge that will not take it puts buddy mode
        // back where it was before D180 rather than off altogether.
        try {
          await legacy.setItemAsync(key, value);
        } catch {
          throw error;
        }
      }
    },

    async deleteItemAsync(key) {
      await bridge.deleteItemAsync(key);
      // Both, always. Switching buddy mode off must not leave a usable secret behind in the place
      // this app has stopped reading from.
      try {
        await legacy.deleteItemAsync(key);
      } catch {
        // Nothing to do: the copy that is used is gone.
      }
    },
  };
}

export function createExpoSecureStorage(): SecureStorage {
  const load = () =>
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    require('expo-secure-store') as typeof import('expo-secure-store');
  return {
    getItemAsync: (key) => load().getItemAsync(key),
    setItemAsync: (key, value) => load().setItemAsync(key, value),
    deleteItemAsync: (key) => load().deleteItemAsync(key),
  };
}

function isCredentials(value: unknown): value is BuddyCredentials {
  if (typeof value !== 'object' || value === null) return false;
  const record = value as Record<string, unknown>;
  return (
    typeof record.deviceId === 'string' &&
    /^[0-9a-f]{32}$/.test(record.deviceId) &&
    typeof record.secret === 'string' &&
    record.secret.length >= 16
  );
}

export interface BuddyCredentialStore {
  /** What this phone is to the relay, or `null` when it has never registered. */
  read(): Promise<BuddyCredentials | null>;
  save(credentials: BuddyCredentials): Promise<boolean>;
  /** Called when buddy mode is switched off. The relay is told separately. */
  clear(): Promise<void>;
}

export function createBuddyCredentialStore(
  storage: SecureStorage = createMigratingSecureStorage(
    createBridgeSecureStorage(),
    createExpoSecureStorage()
  )
): BuddyCredentialStore {
  return {
    async read() {
      let raw: string | null;
      try {
        raw = await storage.getItemAsync(KEY);
      } catch {
        return null;
      }
      if (typeof raw !== 'string' || raw.length === 0) return null;
      try {
        const parsed: unknown = JSON.parse(raw);
        return isCredentials(parsed) ? parsed : null;
      } catch {
        return null;
      }
    },

    async save(credentials) {
      try {
        await storage.setItemAsync(KEY, JSON.stringify(credentials));
        return true;
      } catch {
        // Without somewhere safe to keep the secret, buddy mode does not start. Better to stay off
        // than to fall back to ordinary storage for the one value that matters.
        return false;
      }
    },

    async clear() {
      try {
        await storage.deleteItemAsync(KEY);
      } catch {
        // Nothing to do: the caller has already forgotten the pairs this belonged to.
      }
    },
  };
}
